138	function replaceNullsWithUndefined(someObj: any) {
139	  const replacer = (_: any, value: any) =>
140	    String(value) === 'null' || String(value) === 'undefined'
141	      ? undefined
142	      : value;
143	
144	  return JSON.parse(JSON.stringify(someObj, replacer));
145	}
146	
147	const KubernetesStructuredMetadataTableDrawerContent = <
148	  T extends KubernetesDrawerable,
149	>({
150	  toggleDrawer,
151	  object,
152	  renderObject,
153	  kind,
154	}: KubernetesStructuredMetadataTableDrawerContentProps<T>) => {
155	  const [isYaml, setIsYaml] = useState<boolean>(false);
156	
157	  const formatter = useApi(kubernetesClusterLinkFormatterApiRef);
158	  const classes = useDrawerContentStyles();
159	  const cluster = useContext(ClusterContext);
160	  const { value: clusterLink, error } = useAsync(
161	    async () =>
162	      formatter.formatClusterLink({
163	        dashboardUrl: cluster.dashboardUrl,
164	        dashboardApp: cluster.dashboardApp,
165	        dashboardParameters: cluster.dashboardParameters,
166	        object,
167	        kind,
168	      }),
169	    [cluster, object, kind, formatter],
170	  );
171	
172	  return (
173	    <>
174	      <div className={classes.header}>
175	        <Grid container justifyContent="flex-start" alignItems="flex-start">
176	          <Grid item xs={11}>
177	            <Typography variant="h5">
178	              {object.metadata?.name ?? 'unknown name'}
179	            </Typography>
180	          </Grid>
181	          <Grid item xs={1}>
182	            <IconButton
183	              key="dismiss"
184	              title="Close the drawer"
185	              onClick={e => toggleDrawer(e, false)}
186	              color="inherit"
187	            >
188	              <Close className={classes.icon} />
189	            </IconButton>
190	          </Grid>
191	          <Grid item xs={11}>
192	            <Typography color="textSecondary" variant="body1">
193	              {kind}
194	            </Typography>
195	          </Grid>
196	          <Grid item xs={11}>
197	            <FormControlLabel
198	              control={
199	                <Switch
200	                  checked={isYaml}
201	                  onChange={event => {
202	                    setIsYaml(event.target.checked);
203	                  }}
204	                  name="YAML"
205	                />
206	              }
207	              label="YAML"
208	            />
209	          </Grid>
210	        </Grid>
211	      </div>
212	      {error && (
213	        <div className={classes.errorMessage}>
214	          <LinkErrorPanel
215	            cluster={cluster}
216	            errorMessage={error.message || error.toString()}
217	          />
218	        </div>
219	      )}
220	      <div className={classes.options}>
221	        <div>
222	          {clusterLink && (
223	            <BackstageButton
224	              variant="outlined"
225	              color="primary"
226	              size="small"
227	              to={clusterLink}
228	              endIcon={<OpenInNewIcon />}
229	            >
230	              Open Kubernetes Dashboard
231	            </BackstageButton>
232	          )}
233	        </div>
234	      </div>
235	      <div className={classes.content}>
236	        {isYaml && <ManifestYaml object={object} />}
237	        {!isYaml && (
238	          <StructuredMetadataTable
239	            metadata={renderObject(replaceNullsWithUndefined(object))}
240	          />
241	        )}
242	      </div>
243	    </>
244	  );
245	};
