33	const ServiceSummary = ({ service }: ServiceSummaryProps) => {
34	  return (
35	    <Grid
36	      container
37	      direction="row"
38	      justifyContent="space-between"
39	      alignItems="center"
40	      spacing={0}
41	    >
42	      <Grid xs={8} item>
43	        <ServiceDrawer service={service} />
44	      </Grid>
45	
46	      <Grid item>
47	        <Typography variant="subtitle2">
48	          Type: {service.spec?.type ?? '?'}
49	        </Typography>
50	      </Grid>
51	    </Grid>
52	  );
53	};
