55	type ServiceCardProps = {
56	  service: V1Service;
57	};
58	
59	const ServiceCard = ({ service }: ServiceCardProps) => {
60	  const metadata: any = {};
61	
62	  if (service.status?.loadBalancer?.ingress?.length ?? -1 > 0) {
63	    metadata.loadbalancer = service.status?.loadBalancer;
64	  }
65	
66	  if (service.spec?.type === 'ClusterIP') {
67	    metadata.clusterIP = service.spec.clusterIP;
68	  }
69	  if (service.spec?.type === 'ExternalName') {
70	    metadata.externalName = service.spec.externalName;
71	  }
72	
73	  return (
74	    <StructuredMetadataTable
75	      metadata={{
76	        type: service.spec?.type,
77	        ports: service.spec?.ports,
78	        ...metadata,
79	      }}
80	    />
81	  );
82	};
